def evaluate(current_reputation, observation, my_history, round_num):
    """
    Update reputation based on observed action, considering own recent behavior.
    """
    action = observation['action']

    # Compute own recent donation rate (last 20 actions)
    window = 20
    recent = my_history[-window:] if len(my_history) > window else my_history
    if recent:
        donations = 0
        for entry in recent:
            if isinstance(entry, dict):
                if entry.get('action') == 'donate':
                    donations += 1
            elif isinstance(entry, tuple):
                if entry[1] == 'donate':
                    donations += 1
        own_rate = donations / len(recent)
    else:
        own_rate = 0.5  # neutral default

    # Generosity factor: positive if I donate often, negative if I'm stingy
    generosity = own_rate - 0.5  # range [-0.5, 0.5]

    if action == 'donate':
        # Reward donation: larger boost for poor reputation agents, plus own generosity
        base = 0.2
        neediness = max(0.0, -current_reputation) * 0.2  # extra boost for low rep
        delta = base + neediness + generosity * 0.1
    else:
        # Punish defection: harsher for high reputation agents, less harsh if I'm generous
        base = -0.2
        betrayal = -max(0.0, current_reputation) * 0.2  # extra penalty for high rep
        delta = base + betrayal - generosity * 0.1  # generous -> smaller penalty (adds positive)

    new_rep = current_reputation + delta
    return max(-1.0, min(1.0, new_rep))


def decide(recipient_reputation, round_num, my_history):
    """
    Donate if recipient's reputation exceeds a dynamic threshold.
    Threshold increases over rounds and is adjusted by own recent donation rate.
    """
    # Base threshold: starts low, increases linearly up to 0.6
    base_threshold = min(0.0 + round_num * 0.01, 0.6)

    # Own recent donation rate (last 10 actions)
    window = 10
    recent = my_history[-window:] if len(my_history) > window else my_history
    if recent:
        donations = 0
        for entry in recent:
            if isinstance(entry, dict):
                if entry.get('action') == 'donate':
                    donations += 1
            elif isinstance(entry, tuple):
                if entry[1] == 'donate':
                    donations += 1
        own_rate = donations / len(recent)
    else:
        own_rate = 0.5  # neutral default

    # Adjust threshold based on own behavior:
    # If I donate rarely, lower threshold (be more generous) to increase donations.
    # If I donate often, raise threshold (be more selective) to conserve resources.
    if own_rate < 0.3:
        threshold = base_threshold - 0.2
    elif own_rate > 0.5:
        threshold = base_threshold + 0.1
    else:
        threshold = base_threshold

    return recipient_reputation > threshold

