    """
    Donate if recipient's reputation is above a threshold.
    The threshold is based on our own donation rate: if we donated more than half the time,
    we become stricter (threshold = -0.3); otherwise we are more generous (threshold = -0.6).
    This is the reverse of the original pattern, encouraging more donation when we have been stingy.
    """
    if len(my_history) == 0:
        threshold = -0.5  # neutral starting point
    else:
        donations = sum(1 for action in my_history if action == "donate")
        donation_rate = donations / len(my_history)
        if donation_rate > 0.5:
            threshold = -0.3   # stricter (less likely to donate)
        else:
            threshold = -0.6   # more generous (more likely to donate)
    return recipient_reputation > threshold

